import type { ReactNode } from 'react'
import { ArrowDownRight, ArrowRight, ArrowUpRight } from 'lucide-react'

import { cx } from '~/lib/cx'
import styles from './stat.module.scss'

export type StatTrend = 'up' | 'down' | 'flat'

export interface StatProps {
  label: string
  value: ReactNode
  delta?: string
  trend?: StatTrend
  /** Set when a lower value is better (latency, errors). */
  invertTrend?: boolean
  hint?: string
  icon?: ReactNode
  className?: string
}

const TREND_ICON = {
  up: ArrowUpRight,
  down: ArrowDownRight,
  flat: ArrowRight,
} as const

const TREND_LABEL: Record<StatTrend, string> = {
  up: 'up trend',
  down: 'down trend',
  flat: 'no change',
}

export function Stat({
  label,
  value,
  delta,
  trend = 'flat',
  invertTrend = false,
  hint,
  icon,
  className,
}: StatProps) {
  const Icon = TREND_ICON[trend]
  const positive =
    trend === 'flat' ? null : invertTrend ? trend === 'down' : trend === 'up'
  const deltaTone =
    positive == null
      ? styles.toneNeutral
      : positive
        ? styles.tonePositive
        : styles.toneNegative

  return (
    <div className={cx(styles.root, className)}>
      <div className={styles.head}>
        <p className={styles.label}>{label}</p>
        {icon ? (
          <span className={styles.icon} aria-hidden>
            {icon}
          </span>
        ) : null}
      </div>
      <p className={styles.value}>{value}</p>
      {delta || hint ? (
        <div className={styles.meta}>
          {delta ? (
            <span className={cx(styles.delta, deltaTone)}>
              <Icon className={styles.deltaIcon} aria-hidden />
              <span>{delta}</span>
              <span className={styles.srOnly}>{TREND_LABEL[trend]}</span>
            </span>
          ) : null}
          {hint ? <span className={styles.hint}>{hint}</span> : null}
        </div>
      ) : null}
    </div>
  )
}

export interface StatGroupProps {
  children: ReactNode
  className?: string
}

export function StatGroup({ children, className }: StatGroupProps) {
  return <div className={cx(styles.group, className)}>{children}</div>
}

@use 'styles' as vz;

.root {
  padding: vz.space(5);
  border: 1px solid vz.color('border');
  border-radius: vz.radius('xl');
  background: vz.color('card');
  color: vz.color('card-foreground');
  box-shadow: vz.elevation(1);
}

.head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: vz.space(3);
}

.label {
  margin: 0;
  color: vz.color('muted-foreground');
  font-size: vz.font-size('xs');
  font-weight: 500;
  letter-spacing: 0.02em;
  text-transform: uppercase;
}

.icon {
  display: inline-flex;
  flex: none;
  color: vz.color('muted-foreground');

  svg {
    @include vz.icon(4);
  }
}

.value {
  margin: vz.space(2) 0 0;
  font-size: vz.font-size('2xl');
  font-variant-numeric: tabular-nums;
  font-weight: 600;
  letter-spacing: -0.02em;
  line-height: 1.2;
}

.meta {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: vz.space(1) vz.space(2);
  margin-top: vz.space(2);
  font-size: vz.font-size('xs');
}

.delta {
  position: relative;
  display: inline-flex;
  align-items: center;
  gap: 0.125rem;
  font-weight: 500;
}

.delta-icon {
  @include vz.icon(3.5);
}

.tone-neutral {
  color: vz.color('muted-foreground');
}

.tone-positive {
  color: vz.color('success');
}

.tone-negative {
  color: vz.color('destructive');
}

.hint {
  color: vz.color('muted-foreground');
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
  border-width: 0;
}

.group {
  display: grid;
  grid-template-columns: 1fr;
  gap: vz.space(3);
}

@include vz.up('sm') {
  .group {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@include vz.up('xl') {
  .group {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }
}
